import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.CZxGLIO_.js";const p=JSON.parse('{"title":"Task configuration and execution","description":"Choose resident or scheduled tasks and understand command modes, Cron, restart policies and editing.","frontmatter":{"title":"Task configuration and execution","description":"Choose resident or scheduled tasks and understand command modes, Cron, restart policies and editing."},"headers":[],"relativePath":"en/docs/rooster/tasks/index.md","filePath":"en/docs/rooster/tasks/index.md"}'),d={name:"en/docs/rooster/tasks/index.md"};function n(i,e,s,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="task-configuration-and-execution" tabindex="-1">Task configuration and execution <a class="header-anchor" href="#task-configuration-and-execution" aria-label="Permalink to &quot;Task configuration and execution&quot;">​</a></h1><p>Create a disabled task first, run it manually and inspect logs before enabling automation. Enabled means supervision or scheduling is active; running means a command is executing. They are separate states.</p><h2 id="choose-a-task-type" tabindex="-1">Choose a task type <a class="header-anchor" href="#choose-a-task-type" aria-label="Permalink to &quot;Choose a task type&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Behavior</th><th>Resident</th><th>Scheduled</th></tr></thead><tbody><tr><td>Intended use</td><td>Development servers, long-running workers</td><td>Periodic checks, synchronization, scripts</td></tr><tr><td>Enable</td><td>Starts supervision</td><td>Registers Cron</td></tr><tr><td>Disable</td><td>Stops supervision and requests stop for managed executions</td><td>Cancels future triggers; existing runs continue</td></tr><tr><td>Manual run</td><td>Available, including while disabled</td><td>Available, including while disabled</td></tr></tbody></table><p>Use scheduled tasks for short commands that need periodic execution, rather than forcing a resident supervisor to loop them.</p><h2 id="shell-and-direct-execution" tabindex="-1">Shell and direct execution <a class="header-anchor" href="#shell-and-direct-execution" aria-label="Permalink to &quot;Shell and direct execution&quot;">​</a></h2><ul><li><code>shell</code> supports pipelines, redirection and shell syntax, such as <code>echo ready</code>. A custom shell can be selected.</li><li><code>exec</code> takes an executable in <code>command</code> and separate entries in <code>arguments</code>. Do not put a whole shell command in the executable field.</li></ul><p>For a development server, an example is mode <code>exec</code>, executable <code>/absolute/path/to/pnpm</code>, arguments <code>[&quot;dev&quot;]</code>, and the project&#39;s absolute working directory.</p><p>An empty <code>workingDir</code> inherits Rooster&#39;s working directory. Task environment values override the inherited cached environment. Prefer absolute program and directory paths when depending on interpreters, package managers or PATH. A tray-launched process may not share your current terminal environment.</p><h2 id="cron-and-overlap" tabindex="-1">Cron and overlap <a class="header-anchor" href="#cron-and-overlap" aria-label="Permalink to &quot;Cron and overlap&quot;">​</a></h2><p>The five fields are minute, hour, day of month, month and day of week. This is not a six-field expression with seconds.</p><table tabindex="0"><thead><tr><th>Expression</th><th>Meaning</th></tr></thead><tbody><tr><td><code>*/15 * * * *</code></td><td>Every 15 minutes</td></tr><tr><td><code>0 3 * * *</code></td><td>Daily at 03:00</td></tr><tr><td><code>0 9 * * 1-5</code></td><td>Weekdays at 09:00</td></tr><tr><td><code>CRON_TZ=Asia/Shanghai 0 9 * * *</code></td><td>Daily at 09:00 in Shanghai time</td></tr></tbody></table><p>The default timezone is the process&#39;s local timezone. Descriptors such as <code>@hourly</code> are also accepted. Check the next five trigger times shown by the console.</p><p><code>overlapPolicy</code> defaults to <code>skip</code>, preventing a new overlapping execution. <code>parallel</code> allows concurrency. Ensure tasks that modify the same files or data can run concurrently. A conflicting manual run returns <code>409</code>; it does not wait in a queue.</p><h2 id="resident-restart-policy" tabindex="-1">Resident restart policy <a class="header-anchor" href="#resident-restart-policy" aria-label="Permalink to &quot;Resident restart policy&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Meaning</th></tr></thead><tbody><tr><td><code>restartPolicy: on_failure</code></td><td>Default; restart on failure</td></tr><tr><td><code>restartPolicy: always</code></td><td>Restart automatically</td></tr><tr><td><code>restartPolicy: never</code></td><td>Do not restart automatically</td></tr><tr><td><code>maxRetries</code></td><td>Consecutive-failure limit; omitted or <code>0</code> becomes <code>3</code></td></tr><tr><td><code>minRunSeconds</code></td><td>Minimum normal runtime; omitted or <code>0</code> becomes <code>10</code> seconds</td></tr></tbody></table><p>The supervisor treats a nonzero exit or a runtime shorter than <code>minRunSeconds</code> as failure. A quick exit with code 0 can therefore have a successful execution record while the supervisor treats the short run as a failure and retries. Reaching the consecutive-failure limit disables the task. <code>maxRetries=0</code> does not mean unlimited retries.</p><h2 id="stop-edit-and-delete" tabindex="-1">Stop, edit and delete <a class="header-anchor" href="#stop-edit-and-delete" aria-label="Permalink to &quot;Stop, edit and delete&quot;">​</a></h2><p>The edit entry point remains available, but enabled or running tasks show read-only configuration. Disable the task, wait for or stop active executions, confirm none remain, then reopen the editor and save. Deletion has the same preconditions.</p><p>Disabling a scheduled task does not stop a current execution. Stopping a scheduled execution does not cancel future triggers. Stopping an enabled resident execution also disables supervision; manually started executions may require a separate stop.</p><h2 id="instance-wide-limits" tabindex="-1">Instance-wide limits <a class="header-anchor" href="#instance-wide-limits" aria-label="Permalink to &quot;Instance-wide limits&quot;">​</a></h2><p>Set these variables when starting Rooster. Zero or unset disables each limit:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Meaning</th></tr></thead><tbody><tr><td><code>ROOSTER_MAX_CONCURRENT</code></td><td>Maximum active or starting executions across the instance</td></tr><tr><td><code>ROOSTER_MAX_PER_TASK</code></td><td>Maximum concurrent executions per task</td></tr><tr><td><code>ROOSTER_EXECUTION_TIMEOUT</code></td><td>Timeout for all execution types, for example <code>30m</code></td></tr></tbody></table><p>At capacity, manual requests return <code>409</code> and are not queued. Timeouts are recorded as failures with <code>context deadline exceeded</code>. Consider whether a global timeout is appropriate for resident services.</p><hr><p>Sources checked on 2026-11-15：<a href="https://github.com/leancodebox/rooster/blob/96c86ae62c530da51cd6cd0f7b37b3d6fb7e89be/internal/httpapi/agent/references/api.md" target="_blank" rel="noreferrer">Task schema and behavior</a> · <a href="https://github.com/leancodebox/rooster/blob/96c86ae62c530da51cd6cd0f7b37b3d6fb7e89be/internal/roosterapp/limits.go" target="_blank" rel="noreferrer">Instance limits</a>。</p>',26)])])}const m=t(d,[["render",n]]);export{p as __pageData,m as default};
